def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    my_last, opp_last = history[-1]
    total_opp_d = opp.count('D')
    total_opp_c = n - total_opp_d

    # Pure always-cooperators: defect every remaining round late to exploit
    if total_opp_d == 0:
        return 'C' if n < 90 else 'D'

    # Pure always-defectors: defect
    if total_opp_c == 0:
        return 'D'

    # Opponent seems to forgive our defection (cooperates after our D)
    # while also defecting after our C -> classic exploitable pattern.
    # Detect with transition stats, but only once enough signal exists.
    if n >= 8:
        after_c = [opp[i + 1] for i in range(n - 1) if me[i] == 'C']
        after_d = [opp[i + 1] for i in range(n - 1) if me[i] == 'D']
        if len(after_c) >= 3 and len(after_d) >= 3:
            pd_c = after_c.count('D') / len(after_c)
            pd_d = after_d.count('D') / len(after_d)
            # Opponent punishes us when we cooperate but forgives when we defect:
            # rack up DC=5 by defecting repeatedly.
            if pd_d <= 0.3 and pd_c >= 0.5:
                return 'D'
            # Opponent punishes defection strongly -> keep cooperating
            if pd_d >= 0.7 and pd_c <= 0.3:
                return 'C'

    # Opponent basically always defects recently -> defect
    if n >= 5:
        recent = opp[-5:]
        recent_d = recent.count('D')
        if recent_d == 5:
            return 'D'

    # Nearly end of match: exploit a clearly cooperative opponent.
    if n >= 95:
        if total_opp_c * 2 >= n:
            return 'D'
        return 'D' if opp_last == 'D' else 'C'

    # If opponent is very cooperative, mostly cooperate but keep a rare probe
    if total_opp_c >= n - 2 and n < 90:
        if n >= 20 and n % 19 == 0:
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness:
    if opp_last == 'C':
        # Opponent cooperated: cooperate, unless we detect strong exploitability
        return 'C'

    # Opponent just defected. Look at recent streak.
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak_d += 1
        else:
            break

    # Long defection streak: punish hard
    if streak_d >= 3:
        return 'D'

    # Single defection against mostly-cooperative opponent: forgive most of the time
    if total_opp_c >= total_opp_d + 2:
        # Forgive with high probability, but punish once sometimes to deter
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Balanced/defective opponent: retaliate, but occasionally apologize
    # to break alternating retaliation cycles.
    if my_last == 'D' and n >= 5 and opp[-5:].count('D') <= 2:
        return 'C'
    return 'D'
